export type Project = { id: string, name: string, path: string, position: number, createdAt: number, lastOpenedAt: number | null, };

export type BoardNode = { id: string, type: string, x: number, y: number, width: number | null, height: number | null, data: unknown, z: number, };

export type BoardEdge = { id: string, source: string, target: string, data: unknown, };

export type Board = { viewport: unknown, nodes: Array<BoardNode>, edges: Array<BoardEdge>, };

export type BoardChanges = { viewport: unknown | null, upsertNodes: Array<BoardNode>, deleteNodeIds: Array<string>, upsertEdges: Array<BoardEdge>, deleteEdgeIds: Array<string>, };

/**

 * One `claude` in tmux behind an agent node; `worktree` and `branch` are absent for a non-git project.

 */

export type AgentSession = { id: string, projectId: string, nodeId: string, role: string, repo: string, worktree: string | null, branch: string | null, tmuxName: string, claudeSessionId: string, status: string, action: string, 

/**

 * The node that spawned this session: an executor's CEO.

 */

parent: string | null, };

/**

 * Totals of one session over all its transcripts (a `/clear` starts a new one).

 */

export type Usage = { sessionId: string, projectId: string, nodeId: string, role: string, 

/**

 * The node's title when it was first recorded.

 */

task: string, input: number, output: number, cacheRead: number, cacheWrite1h: number, cacheWrite5m: number, 

/**

 * The first turn's prompt: input, cache read and cache write.

 */

firstPrompt: number | null, 

/**

 * Turns that came after an idle gap longer than the cache TTL and read next to nothing from it.

 */

idleMisses: Array<{ gap: string, ttl: string, tokens: number }>, compactions: number, 

/**

 * The last turn's prompt size, the context the session holds now.

 */

context: number | null, 

/**

 * The CEO's context at each wave boundary, just before the app cleared it.

 */

waveContexts: Array<number>, };
